   $$economie-vwo-2019-ii-rookremmers-vraag5.png$$, $$1p 5 Bereken hoeveel procent van de accijnsverhoging door Mores wordt doorberekend in de verkoopprijs bij winstmaximalisatie in scenario 2.$$, array['4fbd3f88-e2a9-4137-a891-ed3686d6d529', 'a0d464ec-de63-47d4-a8c1-8e4a91e344fa', '9920d6b5-e93c-4f7f-b5f4-f35292bf3183', 'a981dd0f-bda0-4802-bc61-b32b103cd34c']::uuid[]),
