   $$economie-vwo-2019-ii-rentebeleid-geeft-onvoldoende-wind-in-de-zeilen-vraag20.png$$, $$2p 20 Verklaar via de arbeidsmarkt dat technologische ontwikkelingen kunnen hebben bijgedragen aan het laag blijven van de inflatie.$$, array['af4330e3-e7a8-4f71-ab10-be1a6ade7bce']::uuid[]),
