   $$economie-vwo-2019-ii-rentebeleid-geeft-onvoldoende-wind-in-de-zeilen-vraag21.png$$, $$2p 21 Verklaar de opmerking van de econoom over de invloed van de internationale handel op het laag blijven van de inflatie in het land.$$, array['af4330e3-e7a8-4f71-ab10-be1a6ade7bce']::uuid[]),
